#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  (( _STAGE_INDEX >= ${FROM_STAGE:-1} )) || return 1
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo root: gh infers the repo, .env and wrangler.jsonc live here.
cd "$(dirname "$0")/.."
REPO="jorgemasta/29n"
# wrangler without a login: every call uses the token captured in stage 1.
wr() { CLOUDFLARE_API_TOKEN="$CLOUDFLARE_API_TOKEN" CLOUDFLARE_ACCOUNT_ID="$CLOUDFLARE_ACCOUNT_ID" npx --yes wrangler "$@"; }

TOTAL_STAGES=8
# ./scripts/setup-wizard.sh 4 → start at stage 4 (earlier ones are skipped).
FROM_STAGE="${1:-1}"
[[ "$FROM_STAGE" =~ ^[1-8]$ ]] || { printf 'Uso: %s [paso 1-8]\n' "$0"; exit 1; }
# Values saved by earlier runs, so any stage works when started with a later FROM_STAGE.
for _k in CLOUDFLARE_API_TOKEN CLOUDFLARE_ACCOUNT_ID ANTHROPIC_API_KEY UMAMI_WEBSITE_ID UMAMI_API_KEY AI_GATEWAY_URL CF_AIG_TOKEN GITHUB_TOKEN DO_FREE; do
  _v=$(_existing "$_k") && [[ -n "$_v" ]] && printf -v "$_k" '%s' "$_v"  || true
done
unset _k _v
# Free question already set up (stage 5) ⇔ the KV binding is uncommented in wrangler.jsonc.
if [[ -z "${DO_FREE:-}" ]]; then
  if grep -q '^ *"kv_namespaces"' wrangler.jsonc; then DO_FREE=1; else DO_FREE=0; fi
fi

# done_already KEY…: true when every KEY is in .env; loads them so later stages can use them.
done_already() {
  local k v
  for k in "$@"; do v=$(_existing "$k") && [[ -n "$v" ]] || return 1; done
  for k in "$@"; do printf -v "$k" '%s' "$(_existing "$k")"; done
  printf '  %s✓%s ya hecho (%s en .env): lo salto\n' "$GREEN" "$RESET" "$*"
}

banner "29N · cuentas y secretos (vigilante, analítica, pregunta libre)"

# ── 1 ─────────────────────────────────────────────────────────────────────
if stage "Cloudflare: API token y Account ID"; then
if ! done_already CLOUDFLARE_API_TOKEN CLOUDFLARE_ACCOUNT_ID; then
say "Necesario para desplegar (a mano y desde el vigilante) y para crear el KV."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → plantilla «Edit Cloudflare Workers» → Use template."
step "Añade dos permisos más: Zone · DNS · Edit y Zone · Zone · Read."
step "Zone Resources: Include · Specific zone · jorgemasta.com. Account Resources: tu cuenta."
step "Continue to summary → Create Token → copia el token (solo se muestra una vez)."
ask_secret CLOUDFLARE_API_TOKEN "Pega el API token:"
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
say ""
say "Compruebo el token y busco tu Account ID…"
CLOUDFLARE_ACCOUNT_ID="" wr whoami 2>&1 | grep -E "Account|│|[0-9a-f]{32}" | sed 's/^/    /' || warn "wrangler whoami falló: revisa el token"
step "Copia el Account ID de la tabla de arriba (32 caracteres hex). También está en dash.cloudflare.com → Workers & Pages, columna derecha."
ask CLOUDFLARE_ACCOUNT_ID "Account ID:"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
fi
pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if stage "Anthropic: workspace con límite de gasto y API key"; then
if ! done_already ANTHROPIC_API_KEY; then
say "La usan el proceso de datos (vigilante) y la pregunta libre. El límite del workspace es el tope duro."
open_url "https://console.anthropic.com/settings/workspaces"
step "Crea un workspace «29n»."
step "En ese workspace, Limits → pon un límite de gasto mensual (≈ 150 €)."
step "Settings → API keys → Create key, asignada al workspace «29n» → copia la clave (sk-ant-…)."
ask_secret ANTHROPIC_API_KEY "Pega la API key:"
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
fi
pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if stage "GitHub: permisos de Actions y etiquetas"; then
say "El vigilante hace push a main y los avisos sin cuenta usan etiquetas."
step "Workflow permissions de $REPO → «Read and write»."
step "Etiquetas «reporte», «falta-partido» y «vigilante» («reneutralizar» la crea el job de apuestas)."
if confirm "¿Lo hago yo con gh ahora?"; then
  if gh api -X PUT "repos/$REPO/actions/permissions/workflow" -f default_workflow_permissions=write -F can_approve_pull_request_reviews=false >/dev/null 2>&1; then
    printf '  %s✓%s Workflow permissions: read and write\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("Workflow permissions «Read and write» (Settings → Actions → General)")
    warn "no pude cambiar los permisos; hazlo en Settings → Actions → General"
  fi
  for l in "reporte:d73a4a:Reportar error en una tarjeta (desde la web)" "falta-partido:0e8a16:Falta un partido (desde la web)" "vigilante:5319E7:Aviso del vigilante de programas"; do
    IFS=: read -r name color desc <<<"$l"
    if gh label create "$name" --color "$color" --description "$desc" --force -R "$REPO" >/dev/null 2>&1; then
      printf '  %s✓%s etiqueta %s\n' "$GREEN" "$RESET" "$name"
    else SKIPPED+=("Etiqueta $name"); warn "no pude crear la etiqueta $name"; fi
  done
  note "Si main está protegida, permite el push de GitHub Actions en la regla de la rama."
else
  SKIPPED+=("Workflow permissions «Read and write» y etiquetas reporte / falta-partido / vigilante")
fi
pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if stage "Umami (opcional): analítica sin cookies en stats.padelful.com"; then
say "Tu instancia self-hosted. El script sale de https://stats.padelful.com/script.js (ya es el valor por defecto)."
if confirm "¿Configuramos Umami ahora?"; then
  open_url "https://stats.padelful.com/settings/websites"
  step "Settings → Websites → Add website → nombre 29N, dominio 29n.jorgemasta.com."
  step "Abre el sitio → Edit → copia el Website ID (formato uuid)."
  ask UMAMI_WEBSITE_ID "Website ID:"
  write_env UMAMI_WEBSITE_ID "$UMAMI_WEBSITE_ID"
  set_var UMAMI_WEBSITE_ID "$UMAMI_WEBSITE_ID"
  say ""
  step "Settings → API keys → Create key → cópiala (la usa la comprobación semanal de apuestas, guesses.yml)."
  ask_secret UMAMI_API_KEY "Umami API key:"
  if curl -fsS -m 15 -H "Authorization: Bearer $UMAMI_API_KEY" "https://stats.padelful.com/api/websites/$UMAMI_WEBSITE_ID" >/dev/null 2>&1; then
    printf '  %s✓%s la API key funciona\n' "$GREEN" "$RESET"
  else
    warn "la API no respondió con esa key (la guardo igualmente)"
  fi
  write_env UMAMI_API_KEY "$UMAMI_API_KEY"
  set_secret UMAMI_API_KEY "$UMAMI_API_KEY"
else
  SKIPPED+=("Umami: UMAMI_WEBSITE_ID (variable) y UMAMI_API_KEY (secreto)")
fi
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if stage "Pregunta libre (opcional, ~18-nov): KV QUESTIONS"; then
DO_FREE=0
say "Las etapas 6–9 preparan la pregunta libre y los avisos sin cuenta. No la abren:"
note "eso es FREE_QUESTION=\"1\" en wrangler.jsonc + PUBLIC_FREE_QUESTION=1 al desplegar (docs/deploy.md)."
if confirm "¿Preparamos ya la pregunta libre?"; then
  DO_FREE=1
  if grep -qE '^\s*"kv_namespaces"' wrangler.jsonc; then
    say "wrangler.jsonc ya tiene kv_namespaces: no creo otro."
  else
    say "Creo el namespace con wrangler…"
    out=$(wr kv namespace create QUESTIONS 2>&1) || { printf '%s\n' "$out" | sed 's/^/    /'; }
    KV_ID=$(printf '%s' "$out" | grep -oE '[0-9a-f]{32}' | tail -n1 || true)
    if [[ -n "$KV_ID" ]]; then
      sed -i.bak -E "s#^(\s*)// \"kv_namespaces\": \[\{ \"binding\": \"QUESTIONS\", \"id\": \"<id>\" \}\],#\1\"kv_namespaces\": [{ \"binding\": \"QUESTIONS\", \"id\": \"$KV_ID\" }],#" wrangler.jsonc && rm -f wrangler.jsonc.bak
      if grep -q "$KV_ID" wrangler.jsonc; then
        printf '  %s✓%s KV %s escrito en wrangler.jsonc (haz commit)\n' "$GREEN" "$RESET" "$KV_ID"
      else
        SKIPPED+=("Poner el id $KV_ID en kv_namespaces de wrangler.jsonc"); warn "no encontré la línea comentada: pon el id a mano"
      fi
    else
      SKIPPED+=("Crear el KV: npx wrangler kv namespace create QUESTIONS"); warn "no pude crear el KV"
    fi
  fi
else
  SKIPPED+=("Pregunta libre: KV, AI Gateway, GITHUB_TOKEN y secretos del Worker (re-ejecuta el wizard ~18-nov)")
fi
pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if stage "Pregunta libre: AI Gateway sin registros"; then
if (( DO_FREE )); then
  open_url "https://dash.cloudflare.com/$CLOUDFLARE_ACCOUNT_ID/ai/ai-gateway"
  step "Create Gateway → nombre, por ejemplo «29n»."
  step "En Settings del gateway: desactiva Logs (privacidad: no se guardan preguntas)."
  step "Opcional: si activas «Authenticated Gateway», copia su token."
  ask AIG_NAME "Nombre del gateway:"
  AI_GATEWAY_URL="https://gateway.ai.cloudflare.com/v1/$CLOUDFLARE_ACCOUNT_ID/$AIG_NAME/anthropic"
  write_env AI_GATEWAY_URL "$AI_GATEWAY_URL"
  set_secret AI_GATEWAY_URL "$AI_GATEWAY_URL"
  ask_secret CF_AIG_TOKEN "Token del gateway (Enter si no está autenticado):"
  [[ -n "${CF_AIG_TOKEN:-}" ]] && write_env CF_AIG_TOKEN "$CF_AIG_TOKEN"
  note "Pendiente aparte: confirmar en la documentación de AI Gateway si guarda la IP aun con Logs desactivados."
else
  note "Saltada."
fi
pause
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if stage "Avisos sin cuenta: token de GitHub (Issues)"; then
if (( DO_FREE )); then
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Fine-grained token · nombre «29n-avisos» · caducidad: después del 29-nov."
  step "Repository access: Only select repositories → $REPO."
  step "Permissions → Repository → Issues: Read and write. Nada más."
  step "Generate token → cópialo."
  ask_secret GITHUB_TOKEN "Pega el token:"
  write_env GITHUB_TOKEN "$GITHUB_TOKEN"
else
  note "Saltada."
fi
pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if stage "Secretos del Worker (Cloudflare)"; then
if (( DO_FREE )); then
  say "Los secretos del Worker 29n se guardan en Cloudflare, no en el repo."
  if wr secret list >/dev/null 2>&1; then
    for name in ANTHROPIC_API_KEY AI_GATEWAY_URL CF_AIG_TOKEN GITHUB_TOKEN; do
      value="${!name:-}"
      [[ -z "$value" ]] && continue
      if confirm "¿Subo $name al Worker 29n?"; then
        if printf '%s' "$value" | wr secret put "$name" >/dev/null 2>&1; then
          WRITTEN_SECRET+=("worker:$name"); printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$name"
        else SKIPPED+=("Worker secret $name: npx wrangler secret put $name"); warn "falló $name"; fi
      fi
    done
  else
    warn "El Worker 29n aún no existe (se crea con el primer npm run deploy)."
    SKIPPED+=("Tras el primer despliegue: re-ejecuta este wizard (Enter conserva los valores) para subir los secretos del Worker")
  fi
else
  note "Saltada."
fi
pause
fi

finish
say "Siguiente: datos reales (npm run process) y npm run deploy. Ver docs/deploy.md."
say ""
}

run_wizard "$@"; exit
